// tenant-lint: cross-org mükellef yüklemesi için görevi kilitler; taxpayer_id ve aktif engagement ile sınırlı
func (q *Queries) LockTaxpayerDocumentTask(ctx context.Context, arg LockTaxpayerDocumentTaskParams) (LockTaxpayerDocumentTaskRow, error) {
	row := q.db.QueryRow(ctx, lockTaxpayerDocumentTask, arg.TaxpayerID, arg.Uuid)
	var i LockTaxpayerDocumentTaskRow
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.EngagementID,
		&i.TaxpayerID,
		&i.BankTransactionID,
		&i.Status,
		&i.Kind,
		&i.Title,
		&i.CreatedBy,
	)
	return i, err
}

const markDocumentTasksReminded = `-- name: MarkDocumentTasksReminded :execrows
UPDATE document_tasks
SET reminder_count = reminder_count + 1,
    last_reminded_at = $1,
    next_reminder_at = CASE
        WHEN reminder_count + 1 >= $2::int THEN NULL
        ELSE $1::timestamptz + make_interval(days => $3::int * power(2, LEAST(reminder_count + 1, 8))::int)
    END
WHERE organization_id = $4 AND engagement_id = $5
  AND id = ANY ($6::bigint[]) AND status = 'open'
`

type MarkDocumentTasksRemindedParams struct {
	Now            pgtype.Timestamptz `json:"now"`
	MaxReminders   int32              `json:"max_reminders"`
	BaseDays       int32              `json:"base_days"`
	OrganizationID int64              `json:"organization_id"`
	EngagementID   int64              `json:"engagement_id"`
	Ids            []int64            `json:"ids"`
}

// Geri çekilme: n. hatırlatmadan sonra bir sonraki base_days * 2^n gün sonra;
// max_reminders'a ulaşınca hatırlatma biter (next_reminder_at NULL).
func (q *Queries) MarkDocumentTasksReminded(ctx context.Context, arg MarkDocumentTasksRemindedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markDocumentTasksReminded,
		arg.Now,
		arg.MaxReminders,
		arg.BaseDays,
		arg.OrganizationID,
		arg.EngagementID,
		arg.Ids,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const rerequestDocumentTask = `-- name: RerequestDocumentTask :execrows
UPDATE document_tasks
SET status = 'open', note = $1, due_at = $2, next_reminder_at = $3,
    reminder_count = 0, last_reminded_at = NULL, request_count = request_count + 1
WHERE organization_id = $4 AND engagement_id = $5 AND uuid = $6
  AND status = 'submitted'
`

type RerequestDocumentTaskParams struct {
	Note           string             `json:"note"`
	DueAt          pgtype.Timestamptz `json:"due_at"`
	NextReminderAt pgtype.Timestamptz `json:"next_reminder_at"`
	OrganizationID int64              `json:"organization_id"`
	EngagementID   int64              `json:"engagement_id"`
	Uuid           uuid.UUID          `json:"uuid"`
}

// Yüklenen belge yeterli değil: görev yeniden açılır, son tarih ve
// hatırlatma baştan kurulur.
func (q *Queries) RerequestDocumentTask(ctx context.Context, arg RerequestDocumentTaskParams) (int64, error) {
	result, err := q.db.Exec(ctx, rerequestDocumentTask,
		arg.Note,
		arg.DueAt,
		arg.NextReminderAt,
		arg.OrganizationID,
		arg.EngagementID,
		arg.Uuid,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setDocumentTaskStatus = `-- name: SetDocumentTaskStatus :exec
UPDATE document_tasks
SET status = $1,
    submitted_at = COALESCE(submitted_at, NOW()),
    matched_at = CASE WHEN $1 = 'matched' THEN NOW() ELSE matched_at END,
    next_reminder_at = NULL
WHERE organization_id = $2 AND engagement_id = $3 AND id = $4
  AND status IN ('open', 'submitted')
`

type SetDocumentTaskStatusParams struct {
	Status         string `json:"status"`
	OrganizationID int64  `json:"organization_id"`
	EngagementID   int64  `json:"engagement_id"`
	ID             int64  `json:"id"`
}

// matched: belge eşlendi; submitted: yüklendi, ofis bakacak. Hatırlatma durur.
func (q *Queries) SetDocumentTaskStatus(ctx context.Context, arg SetDocumentTaskStatusParams) error {
	_, err := q.db.Exec(ctx, setDocumentTaskStatus,
		arg.Status,
		arg.OrganizationID,
		arg.EngagementID,
		arg.ID,
	)
	return err
}
